function extractCustomerContacts(value){const text=String(value||'');const emails=[...new Set((text.match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi)||[]).map(x=>x.toLowerCase()))],phones=new Set();for(const raw of text.match(/(?:\+|00)?\d[\d\s().-]{5,}\d/g)||[]){let digits=raw.replace(/\D/g,'');if(digits.startsWith('00'))digits=digits.slice(2);if(digits.length<7||digits.length>15)continue;phones.add(digits);if(digits.length===13&&digits.startsWith('86'))phones.add(digits.slice(2));if(digits.length===11&&digits.startsWith('1'))phones.add(digits.slice(1))}return {emails,phones:[...phones]}}
