async function uploadDeliveryProof(orderId,file){if(!file?.size)throw Error('请选择签收证明图片');const path=`${orderId}/delivery-proof-${crypto.randomUUID()}-${file.name}`;const r=await fetch(`${cfg.url}/storage/v1/object/order-images/${path}`,{method:'POST',headers:{apikey:cfg.key,Authorization:`Bearer ${session.access_token}`,'Content-Type':file.type},body:file});if(!r.ok)throw Error('签收证明上传失败');await api('/rest/v1/order_images',{method:'POST',body:JSON.stringify({order_id:orderId,object_path:path,file_name:'签收证明 · '+file.name})})}
async function uploadImages(orderId,files){for(const file of files){const path=`${orderId}/${crypto.randomUUID()}-${file.name}`;const r=await fetch(`${cfg.url}/storage/v1/object/order-images/${path}`,{method:'POST',headers:{apikey:cfg.key,Authorization:`Bearer ${session.access_token}`,'Content-Type':file.type},body:file});if(!r.ok)throw Error('图片上传失败');await api('/rest/v1/order_images',{method:'POST',body:JSON.stringify({order_id:orderId,object_path:path,file_name:file.name})})}}
function detailHtml(o){const follower=profile.role==='follower',supervisor=profile?.email?.toLowerCase()==='505863160@qq.com',flow=flowFor(o),pos=Math.max(0,flow.indexOf(o.current_step)),pct=flow.length>1?Math.round(pos/(flow.length-1)*100):100,canRollback=follower&&pos>0&&!o.rollback_used&&!o.deleted_at;return `<div class="detail"><button class="x" type="button">×</button><div class="detail-title"><div><p class="kicker">${esc(o.order_no)}</p><h2>${esc(o.product_name)} × ${o.quantity}</h2>${returningCustomerHtml(o)}</div>${o.deleted_at?'<span class="recycle-badge">回收站</span>':badge(o)}</div><div class="progress"><div style="width:${pct}%"></div></div><div class="progress-labels"><span>${STEP_LABELS[flow[0]]}</span><b>${pct}% · ${STEP_LABELS[o.current_step]}</b><span>${STEP_LABELS[flow[flow.length-1]]}</span></div><section class="stage-history"><div class="stage-history-head"><div><h3>步骤时间线</h3><span>同时监控当前步骤与全程累计进度</span></div><div class="timeline-alert-summary">${badge(o)}</div></div><div id="orderTimeline" class="timeline-list"><p>正在加载步骤记录...</p></div></section><dl><div><dt>当前步骤</dt><dd>${STEP_LABELS[o.current_step]}</dd></div><div><dt>当前步骤截止</dt><dd>${o.step_deadline?new Date(o.step_deadline).toLocaleString('zh-CN'):'无'}</dd></div><div><dt>累计计划截止</dt><dd>${overallDeadline(o)?new Date(overallDeadline(o)).toLocaleString('zh-CN'):'已完成'}</dd></div><div><dt>尺寸</dt><dd>${esc(o.size)}</dd></div><div><dt>客户信息</dt><dd>${esc(o.customer_info)}</dd></div><div><dt>工厂</dt><dd>${esc(o.factory_name||'-')}</dd></div><div><dt>货代</dt><dd>${esc(o.forwarder_name||'-')}</dd></div><div><dt>订单要求</dt><dd>${esc(o.requirements||'-')}</dd></div><div class="tracking-detail"><dt>物流单号</dt><dd>${trackingEntries(o).length?trackingEntries(o).map(x=>`<span><b>${esc(STEP_LABELS[x.step]||x.step)}</b>${esc(x.number)}</span>`).join(''):'-'}</dd></div></dl>${proofApplies(o)?`<section class="delivery-proof ${needsDeliveryProof(o)?'missing':'complete'}"><div><p class="kicker">DELIVERY PROOF</p><h3>${needsDeliveryProof(o)?'签收证明待补':'签收证明已完成'}</h3><span>${needsDeliveryProof(o)?'订单已送达，请上传签收证明图片。':`上传于 ${new Date(proofRecord(o).created_at).toLocaleString('zh-CN')}`}</span></div>${follower&&needsDeliveryProof(o)?`<form id="proofForm"><input name="proof" type="file" accept="image/*" required><button class="primary">上传签收证明</button><p class="error"></p></form>`:''}</section>`:''}<section class="image-section"><div><h3>产品图片与签收证明</h3><span id="imageCount"></span></div><div id="orderImages" class="image-grid"><p>正在加载图片...</p></div></section>${o.deleted_at&&supervisor?`<div class="actions"><button id="restoreOrder">恢复订单</button><button class="danger" id="permanentDelete">彻底删除</button></div>`:follower?`<div class="actions"><button id="editOrder">编辑订单</button>${canRollback?`<button class="rollback" id="rollback">回退上一步</button>`:""}${o.current_step!=='completed'?`<button class="primary" id="advance">${o.current_step==='production'?'完成生产并发货':o.current_step==='ready_to_ship'||o.current_step==='shipping_selection'?'选择物流并开始发货':o.current_step==='tracking'?'填写物流单号并进入下一步':['ocean_transit','last_mile'].includes(o.current_step)?'填写单号并完成当前步骤':'确认完成当前步骤'}</button>`:""}<button class="danger" id="deleteOrder">删除订单</button></div>`:""}</div>`}
function bind(){$('#orderSearch')?.addEventListener('input',e=>{searchQuery=e.target.value;currentPage=1;clearTimeout(searchTimer);searchTimer=setTimeout(()=>{render();const input=$('#orderSearch');if(input){input.focus();const end=input.value.length;input.setSelectionRange(end,end)}},180)});$('#partnerFilter')?.addEventListener('change',e=>{partnerFilter=e.target.value;factoryFilter='all';businessFilter='all';currentPage=1;render()});$('#factoryFilter')?.addEventListener('change',e=>{factoryFilter=e.target.value;partnerFilter='all';businessFilter='all';currentPage=1;render()});$('#businessFilter')?.addEventListener('change',e=>{businessFilter=e.target.value;partnerFilter='all';factoryFilter='all';currentPage=1;render()});$('#imageResource')?.addEventListener('click',()=>{let d=$('#resourceDialog');d.innerHTML='<div class="resource-modal"><button class="x">×</button><p class="kicker">IMAGE DOWNLOAD</p><h2>图片下载</h2><p>打开下载页面后请输入以下密码。</p><div class="password-box"><span>访问密码</span><b>5863160</b><button id="copyPassword">复制密码</button></div><a class="primary resource-open" href="https://bj36080.apps.aliyunfile.com/disk/s/vdvrmrh6Xnh?pwd=5863160&domainId=bj36080" target="_blank" rel="noopener">打开图片下载</a></div>';d.showModal();d.querySelector('.x').onclick=()=>d.close();d.querySelector('#copyPassword').onclick=async e=>{await navigator.clipboard.writeText('5863160');e.target.textContent='已复制'}});document.querySelectorAll('[data-alert]').forEach(b=>b.onclick=()=>{alertFilter=b.dataset.alert;statusFilter=alertFilter==='proof'?'delivered':'active';currentPage=1;render()});document.querySelectorAll('[data-status]').forEach(b=>b.onclick=()=>{statusFilter=b.dataset.status;alertFilter='all';currentPage=1;render()});document.querySelectorAll('.x').forEach(b=>b.onclick=()=>b.closest('dialog').close());$('#logout')?.addEventListener('click',()=>{clearSession();profile=null;orders=[];render()});$('#login')?.addEventListener('click',()=>$('#auth').showModal());$('#login2')?.addEventListener('click',()=>$('#auth').showModal());
 function authErrorMessage(message){const m=String(message||'');if(/email rate limit exceeded|over_email_send_rate_limit/i.test(m))return '注册邮件发送次数已达上限，请稍后再试；这与密码无关。';if(/password.*(least|short|characters)|weak_password/i.test(m))return '密码至少填写 6 位，可以全部使用数字。';if(/already registered|user_already_exists/i.test(m))return '该邮箱已经注册，请直接点击“登录”。';if(/invalid login credentials/i.test(m))return '邮箱或密码不正确。';return m||'登录或注册失败，请稍后重试。'}
 $('#authForm').onsubmit=async e=>{e.preventDefault();let d=new FormData(e.target),button=e.submitter,mode=button.value;button.disabled=true;e.target.querySelector('.error').textContent='';try{let r=await api(mode==='signup'?'/auth/v1/signup':'/auth/v1/token?grant_type=password',{method:'POST',body:JSON.stringify({email:d.get('email'),password:d.get('password'),data:{follower_invite:inviteToken||''}})});if(!r.access_token)throw Error('注册成功，请打开邮箱完成验证后再登录。');saveSession(r);await refresh()}catch(x){e.target.querySelector('.error').textContent=authErrorMessage(x.message)}finally{button.disabled=false}};
 $('#newOrder')?.addEventListener('click',()=>{let d=$('#orderDialog');d.innerHTML=orderForm();d.showModal();d.querySelector('.x').onclick=()=>d.close();bindCustomerCheck(d.querySelector('form'));d.querySelector('form').onsubmit=async e=>{e.preventDefault();let f=new FormData(e.target),payload=Object.fromEntries([...f].filter(([k])=>k!=='images'));payload.quantity=Number(payload.quantity);payload.needs_rendering=payload.needs_rendering==='true';['shipping_mode','sea_region','overseas_method'].forEach(k=>{if(!payload[k])payload[k]=null});let step=firstStep(payload),initialStart=new Date(payload.order_date+'T00:00:00');payload.current_step=step.key;payload.step_started_at=initialStart.toISOString();payload.step_deadline=deadline(step.days,initialStart);try{let [o]=await api('/rest/v1/orders',{method:'POST',body:JSON.stringify(payload)});await api('/rest/v1/order_events',{method:'POST',body:JSON.stringify({order_id:o.id,step_key:step.key,started_at:o.step_started_at,deadline_at:o.step_deadline})});await uploadImages(o.id,f.getAll('images').filter(x=>x.size));await refresh()}catch(x){e.target.querySelector('.error').textContent=x.message}}});
 document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{if(b.disabled)return;currentPage=Number(b.dataset.page);render();document.querySelector('.order-panel')?.scrollIntoView({behavior:'smooth',block:'start'})});document.querySelectorAll('[data-order]').forEach(c=>c.onclick=()=>{let o=orders.find(x=>x.id===c.dataset.order),d=$('#detail');d.innerHTML=detailHtml(o);d.showModal();loadOrderImages(o.id);loadOrderTimeline(o.id);const proofForm=d.querySelector('#proofForm');if(proofForm)proofForm.onsubmit=async e=>{e.preventDefault();const file=new FormData(proofForm).get('proof');try{await uploadDeliveryProof(o.id,file);d.close();await refresh()}catch(x){proofForm.querySelector('.error').textContent=x.message}};d.querySelector('.x').onclick=()=>d.close();d.querySelector('#editOrder')?.addEventListener('click',()=>editExisting(o));d.querySelector('#rollback')?.addEventListener('click',async()=>{if(!confirm('确定回退到上一个步骤吗？本次回退后，必须再次向前完成一步，才能再次回退。'))return;await rollbackOrder(o);d.close()});d.querySelector('#deleteOrder')?.addEventListener('click',async()=>{if(!confirm('确定删除订单 '+o.order_no+' 吗？删除后只有主管账号能在回收站查看、恢复或彻底删除。'))return;await api('/rest/v1/rpc/soft_delete_order',{method:'POST',body:JSON.stringify({target_order_id:o.id})});d.close();await refresh()});d.querySelector('#restoreOrder')?.addEventListener('click',async()=>{await api('/rest/v1/rpc/restore_deleted_order',{method:'POST',body:JSON.stringify({target_order_id:o.id})});d.close();statusFilter='active';await refresh()});d.querySelector('#permanentDelete')?.addEventListener('click',async e=>{if(String(prompt('彻底删除后无法恢复。请输入订单号确认：')||'').trim()!==String(o.order_no).trim())return;const button=e.currentTarget;button.disabled=true;button.textContent='正在彻底删除…';try{await permanentlyDeleteOrder(o);d.close();await refresh()}catch(x){button.disabled=false;button.textContent='彻底删除';alert('彻底删除失败：'+x.message)}});d.querySelector('#advance')?.addEventListener('click',()=>advanceOrder(o,d))});
 $('#users')?.addEventListener('click',()=>showInvites());if(!session&&registration)$('#auth').showModal();$('#partners')?.addEventListener('click',()=>managePartners())}
async function completeStage(o,next,extra={},fixedDue=null,operationDate=null){if(stageTransitionBusy)throw Error('正在处理当前步骤，请勿重复点击');stageTransitionBusy=true;try{const occurredAt=operationDate||new Date().toISOString(),due=fixedDue||deadline(next.days,new Date(occurredAt));if(next.key!=='completed'&&!due)throw Error('下一阶段必须有截止时间');const [latest]=await api('/rest/v1/orders?id=eq.'+o.id+'&select=current_step');if(!latest)throw Error('订单不存在或已被删除');if(latest.current_step!==o.current_step){await refresh();throw Error('订单已在其他页面推进，已自动刷新，请按最新步骤操作');}const duplicate=await api('/rest/v1/order_events?order_id=eq.'+o.id+'&step_key=eq.'+next.key+'&select=id&limit=1');if(duplicate.length){await refresh();throw Error('该步骤已经发生过，系统已阻止重复执行');}const activeRows=await api('/rest/v1/order_events?order_id=eq.'+o.id+'&completed_at=is.null&select=id,step_key');if(activeRows.length!==1||activeRows[0].step_key!==o.current_step){await refresh();throw Error('当前步骤记录异常，系统已停止推进并自动刷新');}const active=activeRows[0];await api('/rest/v1/rpc/transition_order_stage',{method:'POST',body:JSON.stringify({target_order_id:o.id,target_next_step:next.key,target_deadline:due,target_shipping:extra.shipping_mode?extra:null,target_tracking_no:o.current_step==='tracking'?(extra.tracking_no||null):null})});const corrections=[];if(active){const stageNumber=(extra.stage_tracking_no||extra.tracking_no||'').trim();corrections.push(api('/rest/v1/order_events?id=eq.'+active.id,{method:'PATCH',body:JSON.stringify({completed_at:occurredAt,completed_by:session.user.id,...(stageNumber?{note:TRACKING_NOTE_PREFIX+stageNumber}:{})})}))};corrections.push(api('/rest/v1/order_events?order_id=eq.'+o.id+'&completed_at=is.null&step_key=eq.'+next.key,{method:'PATCH',body:JSON.stringify({started_at:occurredAt})}));corrections.push(api('/rest/v1/orders?id=eq.'+o.id,{method:'PATCH',body:JSON.stringify({step_started_at:occurredAt,updated_at:new Date().toISOString()})}));await Promise.allSettled(corrections)}finally{stageTransitionBusy=false}}
function operationDateValue(value){return new Date(value+'T00:00:00').toISOString()}
function advanceOrder(o,detailDialog){if(['production','ready_to_ship','shipping_selection'].includes(o.current_step))return openShippingSetup(o,detailDialog);if(o.current_step==='tracking')return openTrackingSetup(o,detailDialog);return openStageCompletion(o,detailDialog)}
function openStageCompletion(o,detailDialog){let d=$('#orderDialog'),today=new Date().toISOString().slice(0,10),needsNumber=['ocean_transit','last_mile'].includes(o.current_step),savedNumber=trackingForStep(o,o.current_step);d.innerHTML=`<form id="stageDateForm"><button class="x" type="button">×</button><p class="kicker">STAGE COMPLETE</p><h2>完成“${STEP_LABELS[o.current_step]}”</h2><p class="form-note">${needsNumber?'填写本阶段单号并确认完成；下一阶段将从操作日期重新独立计时。':'默认使用今天；导入旧订单时可以选择实际发生日期。'}</p><div class="${needsNumber?'grid':''}">${needsNumber?`<label>${STEP_LABELS[o.current_step]}单号 *<input name="stage_tracking_no" value="${esc(savedNumber)}" required autofocus></label>`:''}<label>操作日期 *<input name="operation_date" type="date" value="${today}" required></label></div><p class="error"></p><button class="primary">确认完成并进入下一步</button></form>`;d.showModal();const form=d.querySelector('form');d.querySelector('.x').onclick=()=>d.close();form.onsubmit=async e=>{e.preventDefault();try{const values=new FormData(form),operationDate=operationDateValue(values.get('operation_date')),next=nextStep(o,o.current_step),fixedDue=o.current_step==='rendering'?deadline(11,new Date(o.order_date+'T00:00:00')):null,stageNumber=needsNumber?String(values.get('stage_tracking_no')||'').trim():'';if(needsNumber&&!stageNumber)throw Error('请填写本阶段单号');await completeStage(o,next,stageNumber?{stage_tracking_no:stageNumber}:{},fixedDue,operationDate);d.close();detailDialog.close();await refresh()}catch(x){form.querySelector('.error').textContent=x.message}}}
function openShippingSetup(o,detailDialog){let d=$('#orderDialog'),forwarders=partners.filter(p=>p.kind==='forwarder');d.innerHTML=`<form id="shippingForm"><button class="x" type="button">×</button><p class="kicker">SHIPPING SETUP</p><h2>${o.current_step==='production'?'完成生产并发货':'选择物流并开始发货'}</h2><p class="form-note">保存后将完成“${STEP_LABELS[o.current_step]}”，记录发货交接，并在同一时刻立即进入有截止日期的下一阶段。</p><div class="grid"><label>操作／实际发货日期 *<input name="shipped_at" type="date" value="${o.shipped_at?new Date(o.shipped_at).toISOString().slice(0,10):new Date().toISOString().slice(0,10)}" required></label><label>发货方式 *<select name="shipping_mode" required><option value="" disabled ${!o.shipping_mode?'selected':''}>请选择</option><option value="domestic_express" ${o.shipping_mode==='domestic_express'?'selected':''}>国内快递</option><option value="domestic_sea" ${o.shipping_mode==='domestic_sea'?'selected':''}>国内发海运</option><option value="overseas_warehouse" ${o.shipping_mode==='overseas_warehouse'?'selected':''}>海外仓发货</option></select></label><label>物流商 / 货代 *<input name="forwarder_name" value="${esc(o.forwarder_name||'')}" list="shippingForwarders" required placeholder="请选择或填写"></label><label data-sea>海运区域 *<select name="sea_region"><option value="">请选择</option><option value="non_europe" ${o.sea_region==='non_europe'?'selected':''}>非欧洲</option><option value="europe" ${o.sea_region==='europe'?'selected':''}>欧洲</option></select></label><label data-warehouse>海外仓方式 *<select name="overseas_method"><option value="">请选择</option><option value="express" ${o.overseas_method==='express'?'selected':''}>快递</option><option value="truck" ${o.overseas_method==='truck'?'selected':''}>卡派</option></select></label></div><datalist id="shippingForwarders">${forwarders.map(p=>`<option value="${esc(p.name)}">`).join('')}</datalist><p class="error"></p><button class="primary">确认并开始计时</button></form>`;d.showModal();const form=d.querySelector('form'),mode=form.elements.shipping_mode,toggle=()=>{form.querySelector('[data-sea]').hidden=mode.value!=='domestic_sea';form.querySelector('[data-warehouse]').hidden=mode.value!=='overseas_warehouse'};toggle();mode.onchange=toggle;d.querySelector('.x').onclick=()=>d.close();form.onsubmit=async e=>{e.preventDefault();let f=new FormData(form),payload={shipping_mode:f.get('shipping_mode'),forwarder_name:f.get('forwarder_name').trim(),sea_region:f.get('sea_region')||null,overseas_method:f.get('overseas_method')||null,shipped_at:new Date(f.get('shipped_at')+'T00:00:00').toISOString()};if(payload.shipping_mode==='domestic_sea'&&!payload.sea_region)return form.querySelector('.error').textContent='请选择海运区域';if(payload.shipping_mode==='overseas_warehouse'&&!payload.overseas_method)return form.querySelector('.error').textContent='请选择海外仓方式';try{let next=nextShipping({...o,...payload});if(next.days==null)throw Error('发货参数不完整，无法开始计时');await completeStage(o,next,payload,deadline(next.days,new Date(payload.shipped_at)),payload.shipped_at);d.close();detailDialog.close();await refresh()}catch(x){form.querySelector('.error').textContent=x.message}}}
function openTrackingSetup(o,detailDialog){let d=$('#orderDialog');d.innerHTML=`<form id="trackingForm"><button class="x" type="button">×</button><p class="kicker">TRACKING</p><h2>填写物流单号</h2><p class="form-note">保存物流单号后，订单进入“等待送达”并立即开始送达计时。</p><div class="grid"><label>物流单号 *<input name="tracking_no" value="${esc(o.tracking_no||'')}" required autofocus></label><label>操作日期 *<input name="operation_date" type="date" value="${new Date().toISOString().slice(0,10)}" required></label></div><p class="error"></p><button class="primary">保存并进入下一步</button></form>`;d.showModal();const form=d.querySelector('form');d.querySelector('.x').onclick=()=>d.close();form.onsubmit=async e=>{e.preventDefault();try{const values=new FormData(form),operationDate=operationDateValue(values.get('operation_date')),next=nextStep(o,o.current_step),trackingNumber=String(values.get('tracking_no')||'').trim();if(!trackingNumber)throw Error('请填写物流单号');await completeStage(o,next,{tracking_no:trackingNumber},null,operationDate);d.close();detailDialog.close();await refresh()}catch(x){form.querySelector('.error').textContent=x.message}}}
async function permanentlyDeleteOrder(o){const images=await api('/rest/v1/order_images?order_id=eq.'+o.id+'&select=object_path');await api('/rest/v1/rpc/permanently_delete_order',{method:'POST',body:JSON.stringify({target_order_id:o.id})});const failed=[];for(const row of images){const safePath=String(row.object_path).split('/').map(encodeURIComponent).join('/');try{const res=await fetch(cfg.url+'/storage/v1/object/order-images/'+safePath,{method:'DELETE',headers:{apikey:cfg.key,Authorization:'Bearer '+session.access_token}});if(!res.ok)failed.push(row.object_path)}catch{failed.push(row.object_path)}}if(failed.length)console.warn('订单已删除，但部分历史图片未能清理',failed)}
async function rollbackOrder(o){await api('/rest/v1/rpc/rollback_order_one_step',{method:'POST',body:JSON.stringify({target_order_id:o.id})});await refresh()}
function manageUsers(){let d=$('#manage');d.innerHTML=`<div class="detail"><button class="x">×</button><h2>用户管理</h2>${profiles.map(p=>`<label>${esc(p.email)}<select data-role="${p.id}"><option value="business" ${p.role==='business'?'selected':''}>业务员</option><option value="follower" ${p.role==='follower'?'selected':''}>跟单</option></select></label>`).join('')}</div>`;d.showModal();d.querySelector('.x').onclick=()=>d.close();d.querySelectorAll('[data-role]').forEach(s=>s.onchange=()=>api(`/rest/v1/profiles?id=eq.${s.dataset.role}`,{method:'PATCH',body:JSON.stringify({role:s.value})}))}
function managePartners(){let d=$('#manage');d.innerHTML=`<div class="detail"><button class="x">×</button><h2>工厂 / 货代</h2>${partners.map(p=>`<p>${p.kind==='factory'?'工厂':'货代'} · ${esc(p.name)}</p>`).join('')}<form id="partnerForm"><select name="kind"><option value="factory">工厂</option><option value="forwarder">货代</option></select><input name="name" required placeholder="名称"><button class="primary">新增</button></form></div>`;d.showModal();d.querySelector('.x').onclick=()=>d.close();d.querySelector('form').onsubmit=async e=>{e.preventDefault();let f=new FormData(e.target);await api('/rest/v1/partners',{method:'POST',body:JSON.stringify(Object.fromEntries(f))});await refresh()}}



async function repairOrderFlow(order,events){const flow=flowFor(order),counts=new Map();for(const event of events)counts.set(event.step_key,(counts.get(event.step_key)||0)+1);const duplicates=[...counts].filter(([key,count])=>count>1&&flow.includes(key)).sort((x,y)=>flow.indexOf(x[0])-flow.indexOf(y[0]));if(!duplicates.length)throw Error('没有检测到重复步骤');const duplicateIndex=flow.indexOf(duplicates[0][0]);let previousIndex=duplicateIndex-1;while(previousIndex>=0&&flow[previousIndex]==='production_shipping')previousIndex--;if(previousIndex<0)throw Error('无法确定可恢复的步骤');const previousKey=flow[previousIndex],previousEvent=events.filter(e=>e.step_key===previousKey).sort((x,y)=>String(x.started_at).localeCompare(String(y.started_at)))[0];if(!previousEvent)throw Error('缺少上一有效步骤记录');const invalid=events.filter(e=>{const p=flow.indexOf(e.step_key);return p>previousIndex||p<0});if(invalid.length)await api('/rest/v1/order_events?id=in.('+invalid.map(e=>e.id).join(',')+')',{method:'DELETE'});await api('/rest/v1/order_events?id=eq.'+previousEvent.id,{method:'PATCH',body:JSON.stringify({completed_at:null,completed_by:null})});const reset={current_step:previousKey,step_started_at:previousEvent.started_at,step_deadline:previousEvent.deadline_at,rollback_used:false,updated_at:new Date().toISOString()};if(previousKey==='production'||previousKey==='shipping_selection')Object.assign(reset,{shipping_mode:null,forwarder_name:null,sea_region:null,overseas_method:null,tracking_no:null});await api('/rest/v1/orders?id=eq.'+order.id,{method:'PATCH',body:JSON.stringify(reset)})}
async function loadOrderTimeline(orderId){let box=$('#orderTimeline');if(!box)return;try{let rows=await api('/rest/v1/order_events?order_id=eq.'+orderId+'&select=*&order=started_at.asc,created_at.asc');if(!rows.length){box.innerHTML='<p class="timeline-empty">暂无步骤记录</p>';return}const rawRows=rows.slice(),fmt=v=>v?new Date(v).toLocaleString('zh-CN',{year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'}):'';const order=orders.find(o=>o.id===orderId),rawCounts=new Map();for(const row of rawRows)rawCounts.set(row.step_key,(rawCounts.get(row.step_key)||0)+1);const corrupted=[...rawCounts].some(([key,count])=>count>1&&flowFor(order).includes(key)),uniqueRows=new Map();for(const row of rows){const saved=uniqueRows.get(row.step_key);if(!saved||(!row.completed_at&&saved.completed_at))uniqueRows.set(row.step_key,row)}rows=[...uniqueRows.values()];const canonical=order?flowFor(order):[],position=key=>{const p=canonical.indexOf(key);return p<0?999:p};rows.sort((x,y)=>position(x.step_key)-position(y.step_key)||String(x.started_at).localeCompare(String(y.started_at)));const productionIndex=rows.findIndex(r=>r.step_key==='production'),productionRow=productionIndex>=0?rows[productionIndex]:null,handoffAt=order?.shipped_at||productionRow?.completed_at;if(order?.inventory_mode!=='stock'&&handoffAt&&!rows.some(r=>r.step_key==='production_shipping'))rows.splice(productionIndex>=0?productionIndex+1:0,0,{step_key:'production_shipping',started_at:handoffAt,completed_at:handoffAt,deadline_at:null});const proof=order?proofRecord(order):null,proofHtml=order&&proofApplies(order)?'<article class="timeline-item '+(proof?'done':'current proof-pending')+'"><i></i><div><b>签收证明</b>'+(proof?'<span>上传：'+fmt(proof.created_at)+'</span><span>完成：'+fmt(proof.created_at)+'</span>':'<span class="timeline-due">待上传 · 黄色提醒</span>')+'</div></article>':'',repairHtml=corrupted?'<div class="flow-repair"><b>检测到历史流程重复，订单已停止继续推进</b><span>请恢复到最后一个有效步骤后重新操作。</span>'+(profile?.role==='follower'?'<button id="repairFlow" class="rollback">修复异常流程</button>':'<span>请联系跟单处理。</span>')+'</div>':'';box.innerHTML=repairHtml+rows.map((row,index)=>'<article class="timeline-item '+(row.completed_at?'done':'current')+'"><i></i><div><b>'+esc(STEP_LABELS[row.step_key]||row.step_key)+'</b>'+(trackingNumberFromNote(row.note)?'<span class="timeline-tracking">单号：'+esc(trackingNumberFromNote(row.note))+'</span>':'')+'<span>进入：'+fmt(row.started_at)+'</span>'+(row.completed_at?'<span>完成：'+fmt(row.completed_at)+'</span>':row.deadline_at?'<span class="timeline-due">进行中 · 截止：'+fmt(row.deadline_at)+'</span>':'<span class="timeline-due">进行中</span>')+'</div></article>').join('')+proofHtml;if(corrupted){const advance=$('#advance');if(advance)advance.disabled=true;box.querySelector('#repairFlow')?.addEventListener('click',async e=>{if(!confirm('将删除错误跳出的后续节点，并恢复到最后一个有效步骤。确定修复吗？'))return;e.currentTarget.disabled=true;try{await repairOrderFlow(order,rawRows);$('#detail')?.close();await refresh()}catch(x){e.currentTarget.disabled=false;alert('修复失败：'+x.message)}})}}catch(e){box.innerHTML='<p class="timeline-empty">步骤记录加载失败：'+esc(e.message)+'</p>'}}
async function loadOrderThumbnails(){const nodes=[...document.querySelectorAll('[data-thumb]')];await Promise.all(nodes.map(async node=>{const orderId=node.dataset.thumb,row=imageRecords.find(x=>x.order_id===orderId&&!x.object_path.includes('/delivery-proof-'));if(!row)return;try{let url=thumbnailCache.get(row.object_path);if(!url){const signed=await api('/storage/v1/object/sign/order-images/'+row.object_path,{method:'POST',body:JSON.stringify({expiresIn:3600})});url=cfg.url+'/storage/v1'+signed.signedURL;thumbnailCache.set(row.object_path,url)}if(document.body.contains(node))node.innerHTML='<img src="'+url+'" alt="'+esc(row.file_name||'产品图片')+'">'}catch{}}))}
async function loadOrderImages(orderId){let box=$('#orderImages');if(!box)return;try{let rows=await api('/rest/v1/order_images?order_id=eq.'+orderId+'&select=*&order=created_at');if(!rows.length){box.innerHTML='<p class="no-images">暂无图片</p>';$('#imageCount').textContent='0 张';return}let cards=[];for(let row of rows){let signed=await api('/storage/v1/object/sign/order-images/'+row.object_path,{method:'POST',body:JSON.stringify({expiresIn:3600})});let url=cfg.url+'/storage/v1'+signed.signedURL;cards.push('<a href="'+url+'" target="_blank" rel="noopener"><img src="'+url+'" alt="'+esc(row.file_name)+'"><span>'+esc(row.file_name)+'</span></a>')}box.innerHTML=cards.join('');$('#imageCount').textContent=rows.length+' 张'}catch(e){box.innerHTML='<p class="no-images">图片加载失败：'+esc(e.message)+'</p>'}}
function editExisting(o){let d=$('#orderDialog');d.innerHTML=orderForm().replace('创建订单','编辑订单');d.showModal();d.querySelector('.x').onclick=function(){d.close()};Object.keys(o).forEach(function(k){let el=d.querySelector('[name="'+k+'"]');if(el&&o[k]!=null)el.value=k==='shipped_at'?new Date(o[k]).toISOString().slice(0,10):typeof o[k]==='boolean'?String(o[k]):o[k]});let form=d.querySelector('form');bindCustomerCheck(form,o.id);form.onsubmit=async function(e){e.preventDefault();let f=new FormData(form),payload=Object.fromEntries(Array.from(f).filter(function(x){return x[0]!=='images'}));payload.quantity=Number(payload.quantity);payload.needs_rendering=payload.needs_rendering==='true';['shipping_mode','sea_region','overseas_method'].forEach(function(k){if(!payload[k])payload[k]=null});let initial=firstStep(payload);if(o.current_step===initial.key){let initialStart=new Date(payload.order_date+'T00:00:00');payload.step_started_at=initialStart.toISOString();payload.step_deadline=deadline(initial.days,initialStart)}try{await api('/rest/v1/orders?id=eq.'+o.id,{method:'PATCH',body:JSON.stringify(payload)});if(payload.step_started_at)await api('/rest/v1/order_events?order_id=eq.'+o.id+'&completed_at=is.null&step_key=eq.'+o.current_step,{method:'PATCH',body:JSON.stringify({started_at:payload.step_started_at,deadline_at:payload.step_deadline})});await uploadImages(o.id,f.getAll('images').filter(function(x){return x.size}));d.close();$('#detail')?.close();await refresh()}catch(x){form.querySelector('.error').textContent=x.message}}}
async function showInvites(){let row=await api('/rest/v1/app_settings?key=eq.follower_invite&select=value').then(function(x){return x[0]});let businessLink=location.origin+'/?register=business',followerLink=location.origin+'/?register=follower&invite='+(row?row.value:'');let d=$('#manage');let users=profiles.map(function(p){let fixed=p.email?.toLowerCase()==='505863160@qq.com';return '<div class="user-role-row"><span><b>'+esc(p.email)+'</b><small>'+(fixed?'主管账号，权限固定':p.role==='follower'?'当前：跟单':'当前：业务员')+'</small></span>'+(fixed?'<strong>主管</strong>':'<select data-role="'+p.id+'" data-email="'+esc(p.email)+'" data-original="'+p.role+'"><option value="business" '+(p.role==='business'?'selected':'')+'>业务员</option><option value="follower" '+(p.role==='follower'?'selected':'')+'>跟单</option></select>')+'</div>'}).join('');d.innerHTML='<div class="detail"><button class="x">×</button><h2>用户管理</h2><label>业务员注册链接<input readonly value="'+businessLink+'"></label><label>跟单邀请链接（请勿公开）<input readonly value="'+followerLink+'"></label><p>点击输入框即可复制。只有主管可以分配账号权限。</p><div id="roleStatus" class="role-status"></div><div class="user-role-list">'+users+'</div></div>';d.showModal();d.querySelector('.x').onclick=function(){d.close()};d.querySelectorAll('input[readonly]').forEach(function(i){i.onclick=function(){i.select();navigator.clipboard.writeText(i.value)}});d.querySelectorAll('[data-role]').forEach(function(s){s.onchange=async function(){let previous=s.dataset.original,status=d.querySelector('#roleStatus');s.disabled=true;status.textContent='正在保存...';try{await api('/rest/v1/rpc/set_user_role',{method:'POST',body:JSON.stringify({target_user_id:s.dataset.role,target_role:s.value})});let p=profiles.find(x=>x.id===s.dataset.role);if(p)p.role=s.value;s.dataset.original=s.value;status.textContent=s.dataset.email+' 已设置为'+(s.value==='follower'?'跟单':'业务员')}catch(e){s.value=previous;status.textContent='保存失败：'+e.message}finally{s.disabled=false}}})}
fetch('/api/config?t='+Date.now(),{cache:'no-store'}).then(r=>r.json()).then(async x=>{cfg=x;startVersionWatch();if(session)await renewSession();return refresh()}).catch(()=>render());
